#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long d;
    if (scanf("%d %lld", &n, &d) != 2) return 0;
    vector<int> r(n);
    for (int i = 0; i < n; i++) {
        long long v;
        scanf("%lld", &v);
        r[i] = (int)(v % d);
    }
    vector<int> freq(d, 0);
    long long ans = 0;
    for (int i = 0; i + 2 < n; i++) {
        // frequencies of residues to the right of i
        for (int k = i + 1; k < n; k++) freq[r[k]]++;
        for (int j = i + 1; j + 1 < n; j++) {
            freq[r[j]]--;
            ans += freq[(2 * d - r[i] - r[j]) % d];
        }
        freq[r[n - 1]]--;  // only k = n-1 is left
    }
    printf("%lld\n", ans);
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long d = nextLong();
        int[] r = new int[n];
        for (int i = 0; i < n; i++) r[i] = (int) (nextLong() % d);
        int[] freq = new int[(int) d];
        long ans = 0;
        for (int i = 0; i + 2 < n; i++) {
            // frequencies of residues to the right of i
            for (int k = i + 1; k < n; k++) freq[r[k]]++;
            for (int j = i + 1; j + 1 < n; j++) {
                freq[r[j]]--;
                ans += freq[(int) ((2 * d - r[i] - r[j]) % d)];
            }
            freq[r[n - 1]]--; // only k = n-1 is left
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, d := int(nextInt()), nextInt()
	r := make([]int64, n)
	for i := range r {
		r[i] = nextInt() % d
	}
	freq := make([]int32, d)
	var ans int64
	for i := 0; i+2 < n; i++ {
		// frequencies of residues to the right of i
		for k := i + 1; k < n; k++ {
			freq[r[k]]++
		}
		for j := i + 1; j+1 < n; j++ {
			freq[r[j]]--
			ans += int64(freq[(2*d-r[i]-r[j])%d])
		}
		freq[r[n-1]]-- // only k = n-1 is left
	}
	fmt.Println(ans)
}
